import sys

def digit_sum(n):
    total = 0
    while n > 0:
        total += n % 10
        n //= 10
    return total

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    S = int(data[0])
    A = int(data[1])
    B = int(data[2])

    count = 0
    for n in range(A, B + 1):
        if digit_sum(n) == S:
            count += 1

    print(count)

if __name__ == "__main__":
